-- One aggregate with atomic version checks preserves the existing club workflow.
-- Authentication and login limits are separate, indexed tables.
CREATE TABLE IF NOT EXISTS club (
 id INTEGER PRIMARY KEY CHECK (id = 1),
 payload TEXT NOT NULL CHECK (json_valid(payload)),
 version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS auth (
 token TEXT PRIMARY KEY,
 role TEXT NOT NULL CHECK (role IN ('bar','reception','admin')),
 expires INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS auth_expiry ON auth(expires);
CREATE TABLE IF NOT EXISTS login_limits (
 ip TEXT NOT NULL,
 bucket INTEGER NOT NULL,
 attempts INTEGER NOT NULL,
 PRIMARY KEY(ip, bucket)
);
